operations.command:
$ErrorActionPreference='Stop'
$p=Join-Path $env:TEMP 'JAA-v0347-input-20260909-184850'
$f=Get-Content "$p/00_governance/JAA_Codex_Delivery_Standard_v2.1.0.md" -Encoding UTF8
$f | Select-Object -Skip 336 -First 8
$f | Select-Object -Skip 670
Get-Content "$p/JAA_v0.3.47_Codex_Input_Manifest.md","$p/02_design/Scope_and_Reading_Plan.md","$p/03_contracts/contract-index.json" -Encoding UTF8
$n=0
foreach($line in Get-Content "$p/SHA256SUMS.txt"){
 if($line -notmatch '^([a-fA-F0-9]{64})\s+\*?(.+)$'){throw 'Invalid SHA manifest line'}
 $expected=$Matches[1];$rel=$Matches[2];$full=[IO.Path]::GetFullPath((Join-Path $p $rel))
 if(-not $full.StartsWith($p+[IO.Path]::DirectorySeparatorChar)){throw 'Unsafe manifest path'}
 if((Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash -ne $expected){throw "Hash mismatch: $rel"};$n++
}
"SHA256 PASS: $n files"
Push-Location $p
try {node 07_validation/validate-input.cjs
if($LASTEXITCODE -ne 0){throw 'Input validator failed'}
python -X utf8 07_validation/test-frozen-ddl.py
if($LASTEXITCODE -ne 0){throw 'DDL validator failed'}
} finally {Pop-Location}
foreach($f in @('F:/AGENTS.md','F:/AI/AGENTS.md','F:/AI/JiraActivityAnalyzer/AGENTS.md','F:/AI/JiraActivityAnalyzer/AI_RULES.md')){if(Test-Path -LiteralPath $f){Get-Content -LiteralPath $f -Encoding UTF8}}
git status --porcelain=v1
git remote -v
git rev-parse --abbrev-ref '@{upstream}'
Get-ChildItem -LiteralPath release -Directory | Where-Object Name -eq '0.3.47'
exit 0

